describe("signIn: turning notifications off (M1.2 §5)", () => {
  const notifications = async () => {
    const { rows } = await db.query<{ user_id: string; outcome: string }>(
      "SELECT user_id, outcome FROM reaction_notifications ORDER BY user_id, reactor_id",
    );
    return rows;
  };

  const digests = async () => {
    const { rows } = await db.query<{ user_id: string }>(
      `SELECT user_id FROM jobs
       WHERE kind = 'deliver' AND payload->>'digest' = 'true' ORDER BY user_id`,
    );
    return rows.map((row) => row.user_id);
  };

  /** Gives the user a delivered and a queued notification, and an open digest. */
  const notified = async (userId: string) => {
    await db.query(
      `INSERT INTO content (node_id, type, repo_full_name, url, title)
       VALUES ($1, 'Issue', 'octo/repo', 'https://github.com/octo/repo/issues/1', 'Bug')
       ON CONFLICT DO NOTHING`,
      [`I_${userId}`],
    );
    for (const reactor of ["R_1", "R_2"]) {
      await db.query(
        `INSERT INTO reaction_events (node_id, reactor_id, emoji, reacted_at, reactor_login)
         VALUES ($1, $2, 'HEART', now(), 'carol')`,
        [`I_${userId}`, reactor],
      );
    }
    await db.query(
      `INSERT INTO reaction_notifications (user_id, node_id, reactor_id, emoji, outcome)
       VALUES ($1, $2, 'R_1', 'HEART', 'delivered'), ($1, $2, 'R_2', 'HEART', 'queued')`,
      [userId, `I_${userId}`],
    );
    await openDigests(db, [userId]);
  };

  it.each(["open", "rendered"])(
    "drops the queued notifications and the %s digest, and keeps the delivered ones",
    async (digestState) => {
      await signInAs("notify");
      await signInAs("notify", BOB, "gho_bob");
      await notified("U_alice");
      await notified("U_bob");
      if (digestState === "rendered") {
        await db.query(
          `UPDATE jobs SET payload = payload || '{"state": "rendered", "body": "x"}'
           WHERE payload->>'digest' = 'true'`,
        );
      }

      await signInAs("summary");

      expect(await digests()).toEqual(["U_bob"]);
      expect(await notifications()).toEqual([
        { user_id: "U_alice", outcome: "delivered" },
        { user_id: "U_bob", outcome: "delivered" },
        { user_id: "U_bob", outcome: "queued" },
      ]);
    },
  );
});

describe("signIn: turning notifications on (M1.2 §6)", () => {
  it("re-stamps enabled_at, raises the item watermarks, and resets the pass watermarks", async () => {
    await signInAs("summary");
    await addSnapshot();
    await db.query(
      `INSERT INTO content (node_id, type, repo_full_name, url, title)
       VALUES ('I_2', 'Issue', 'octo/repo', 'https://github.com/octo/repo/issues/2', 'Bug')`,
    );
    await db.query(
      `INSERT INTO tracked_content (user_id, node_id, last_checked_at, last_event_at,
                                    watermark_at)
       VALUES ('U_alice', 'I_2', now(), now(), now() + interval '1 hour')`,
    );
    await db.query(
      `UPDATE tracked_content SET last_checked_at = now() - interval '1 day',
                                  watermark_at = now() - interval '1 day'
       WHERE node_id = 'I_1'`,
    );
    await db.query(
      "UPDATE subscription_types SET enabled_at = now() - interval '30 days'",
    );
    await db.query(
      "UPDATE subscription_passes SET watermark = now() - interval '30 days'",
    );

    expect((await signInAs("notify")).status).toBe(
      "notifications-on-summary-pending",
    );

    const { rows: types } = await db.query<{ ago: number }>(
      "SELECT extract(epoch FROM now() - enabled_at)::float8 AS ago FROM subscription_types",
    );
    expect(types).toHaveLength(3);
    for (const { ago } of types) {
      expect(ago).toBeCloseTo(defaultConfig.clockMarginSeconds, -1);
    }
    const { rows: passes } = await db.query<{ ago: number }>(
      "SELECT extract(epoch FROM now() - watermark)::float8 AS ago FROM subscription_passes",
    );
    expect(passes).toHaveLength(3);
    for (const { ago } of passes) {
      expect(ago).toBeCloseTo(defaultConfig.searchOverlapSeconds, -1);
    }
    const { rows: items } = await db.query<{
      node_id: string;
      watermark_ago: number;
      checked_ago: number;
    }>(
      `SELECT node_id,
              extract(epoch FROM now() - watermark_at)::float8 AS watermark_ago,
              extract(epoch FROM now() - last_checked_at)::float8 AS checked_ago
       FROM tracked_content ORDER BY node_id`,
    );
    expect(items[0]?.watermark_ago).toBeCloseTo(
      defaultConfig.clockMarginSeconds,
      -1,
    );
    // a newer watermark is kept
    expect(items[1]?.watermark_ago).toBeCloseTo(-3600, -1);
    for (const { checked_ago } of items) {
      expect(checked_ago).toBeCloseTo(0, 0);
    }
  });

  it("recreates a missing sync job", async () => {
    await prepare("summary", true);
    expect((await state()).sync).toBe("none");

    await signInAs("notify");

    expect((await state()).sync).toBe("due");
    const { rows } = await db.query("SELECT 1 FROM jobs WHERE kind = 'sync'");
    expect(rows).toHaveLength(1);
  });
});
